// Upper bound of each stress category (inclusive) [C], its name, its colour (Blazejczyk et al. 2013).
export const UTCI_CATEGORIES = [
  [-40.0, "extreme cold stress", "#08306b"],
  [-27.0, "very strong cold stress", "#08519c"],
  [-13.0, "strong cold stress", "#3182bd"],
  [0.0, "moderate cold stress", "#6baed6"],
  [9.0, "slight cold stress", "#9ecae1"],
  [26.0, "no thermal stress", "#4caf50"],
  [32.0, "moderate heat stress", "#fdd835"],
  [38.0, "strong heat stress", "#fb8c00"],
  [46.0, "very strong heat stress", "#e53935"],
  [Infinity, "extreme heat stress", "#8e0000"],
];

/** Saturation vapour pressure [hPa] over water at t [C] (Hardy 1998, as in the UTCI reference code). */
function esat(t) {
  const g = [-2836.5744, -6028.076559, 19.54263612, -0.02737830188, 0.000016261698, 7.0229056e-10, -1.8680009e-13];
  const tk = t + 273.15;
  let es = 2.7150305 * Math.log1p(tk);
  for (let i = 0; i < g.length; i++) es += g[i] * Math.pow(tk, i - 2);
  return Math.exp(es) * 0.01;
}

/** The polynomial alone, no range check. */
export function utciRaw(ta, tr, va, rh) {
  const pa = esat(ta) * rh / 100 / 10, dt = tr - ta;
  const P = [[1], [1], [1], [1]];
  for (let k = 1; k <= 6; k++) {
    P[0][k] = P[0][k - 1] * ta; P[1][k] = P[1][k - 1] * va; P[2][k] = P[2][k - 1] * dt; P[3][k] = P[3][k - 1] * pa;
  }
  let s = 0;
  for (const [c, a, b, d, e] of TERMS) s += c * P[0][a] * P[1][b] * P[2][d] * P[3][e];
  return s;
}

/** UTCI [C], or NaN outside the index's valid range. */
export function utci(ta, tr, va, rh) {
  if (!(ta > -50 && ta < 50 && tr - ta > -30 && tr - ta < 70 && va >= 0.5 && va <= 17)) return NaN;
  return utciRaw(ta, tr, va, rh);
}

/** The stress category of a UTCI value: { index, label, color }. */
export function utciCategory(u) {
  const k = UTCI_CATEGORIES.findIndex(([hi]) => u <= hi);
  const [, label, color] = UTCI_CATEGORIES[k < 0 ? UTCI_CATEGORIES.length - 1 : k];
  return { index: k, label, color };
}
